**pom.xml (Patched Dependencies)**
```xml
<project>
    <modelVersion>4.0.0</modelVersion>
    <groupId>com.acme</groupId>
    <artifactId>user-service</artifactId>
    <version>1.0.0</version>
    <packaging>jar</packaging>  <!-- SECURE: Use JAR (Spring Boot default) instead of WAR -->

    <!-- SECURE: Updated Spring Framework to patched version -->
    <dependencyManagement>
        <dependencies>
            <dependency>
                <groupId>org.springframework</groupId>
                <artifactId>spring-framework-bom</artifactId>
                <version>5.3.18</version>  <!-- SECURE: Patched version -->
                <type>pom</type>
                <scope>import</scope>
            </dependency>
        </dependencies>
    </dependencyManagement>

    <properties>
        <maven.compiler.source>11</maven.compiler.source>
        <maven.compiler.target>11</maven.compiler.target>
        <spring-boot.version>2.6.6</spring-boot.version>  <!-- SECURE: Includes patched Spring -->
    </properties>

    <dependencies>
        <dependency>
            <groupId>org.springframework.boot</groupId>
            <artifactId>spring-boot-starter-web</artifactId>
            <version>${spring-boot.version}</version>
        </dependency>

        <!-- If WAR deployment is absolutely required, use patched Tomcat -->
        <!-- dependency>
            <groupId>org.apache.tomcat</groupId>
            <artifactId>tomcat-catalina</artifactId>
            <version>9.0.62</version>
        </dependency -->
    </dependencies>

    <build>
        <plugins>
            <!-- SECURE: Maven Enforcer to prevent vulnerable dependencies -->
            <plugin>
                <groupId>org.apache.maven.plugins</groupId>
                <artifactId>maven-enforcer-plugin</artifactId>
                <version>3.0.0-M3</version>
                <executions>
                    <execution>
                        <id>enforce-versions</id>
                        <goals>
                            <goal>enforce</goal>
                        </goals>
                        <configuration>
                            <rules>
                                <requirePluginVersions/>
                                <bannedDependencies>
                                    <excludes>
                                        <exclude>org.springframework:spring-framework-bom:*:pom:jar</exclude>
                                    </excludes>
                                    <includes>
                                        <include>org.springframework:spring-framework-bom:5.2.20:pom:*</include>
                                        <include>org.springframework:spring-framework-bom:5.3.18:pom:*</include>
                                    </includes>
                                </bannedDependencies>
                            </rules>
                        </configuration>
                    </execution>
                </executions>
            </plugin>
        </plugins>
    </build>
</project>
```

**SecureProfileController.java (Tier 1: Critical Fix)**
```java
package com.acme.profiles.secure;

import org.springframework.web.bind.annotation.*;
import org.springframework.web.bind.WebDataBinder;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import javax.validation.Valid;

@RestController
@RequestMapping("/api/profiles")
@Validated
public class SecureProfileController {

    /**
     * SECURE: @InitBinder restricts data binding to specific fields only.
     * This is the critical defense against Spring4Shell.
     */
    @InitBinder
    public void initBinder(WebDataBinder binder) {
        // SECURE: Explicitly allow ONLY the fields we need
        binder.setAllowedFields("name", "email", "phone");

        // SECURE: Explicitly block dangerous patterns (defense in depth)
        // These patterns match the gadget chain used in Spring4Shell
        binder.setDisallowedFields(
            "class",
            "class.*",
            "*.class",
            "*.class.*",
            "Class",
            "Class.*",
            "*.Class",
            "*.Class.*",
            "classLoader",
            "classloader",
            "*.classLoader",
            "*.classloader",
            "module",
            "*.module",
            "protectionDomain",
            "*.protectionDomain",
            "constructor",
            "*.constructor"
        );
    }

    /**
     * SECURE: Accepts @Valid annotated POJO.
     * Combined with @InitBinder, this ensures only allowed fields can be bound.
     */
    @PostMapping("/update")
    public ResponseEntity<String> updateProfile(@Valid ProfileForm form) {
        // Now form object only contains name, email, phone
        // Attempting to pass class.module.classLoader will be silently ignored
        return ResponseEntity.ok("Profile updated: " + form.getName());
    }

    @PostMapping("/create")
    public ResponseEntity<String> createProfile(@Valid UserRegistration reg) {
        return ResponseEntity.ok("User created: " + reg.getUsername());
    }

    // POJOs remain the same - the security is in the controller binding config
    public static class ProfileForm {
        private String name;
        private String email;
        private String phone;

        public String getName() { return name; }
        public void setName(String name) { this.name = name; }

        public String getEmail() { return email; }
        public void setEmail(String email) { this.email = email; }

        public String getPhone() { return phone; }
        public void setPhone(String phone) { this.phone = phone; }
    }

    public static class UserRegistration {
        private String username;
        private String password;
        private String email;

        public String getUsername() { return username; }
        public void setUsername(String username) { this.username = username; }

        public String getPassword() { return password; }
        public void setPassword(String password) { this.password = password; }

        public String getEmail() { return email; }
        public void setEmail(String email) { this.email = email; }
    }
}
```

**Tier 2: Enhanced Input Validation & Monitoring**
```java
package com.acme.profiles.secure;

import org.springframework.context.annotation.Configuration;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.context.request.WebRequest;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;
import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
import org.springframework.web.servlet.HandlerInterceptor;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.util.Enumeration;
import java.util.regex.Pattern;

@Configuration
public class Spring4ShellDefenseConfig implements WebMvcConfigurer {

    private static final Logger log = LoggerFactory.getLogger(Spring4ShellDefenseConfig.class);
    private static final Pattern DANGEROUS_PATTERN = 
        Pattern.compile("(class|classLoader|module|constructor|protectionDomain).*", 
                        Pattern.CASE_INSENSITIVE);

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(new Spring4ShellDetectionInterceptor()).addPathPatterns("/api/**");
    }

    public static class Spring4ShellDetectionInterceptor implements HandlerInterceptor {

        private static final Logger log = LoggerFactory.getLogger(Spring4ShellDetectionInterceptor.class);

        @Override
        public boolean preHandle(HttpServletRequest request, HttpServletResponse response, 
                                Object handler) throws Exception {

            // Check for suspicious parameter names
            Enumeration<String> paramNames = request.getParameterNames();
            while (paramNames.hasMoreElements()) {
                String paramName = paramNames.nextElement();

                // Log any suspicious parameter for analysis
                if (DANGEROUS_PATTERN.matcher(paramName).matches()) {
                    log.warn("SECURITY ALERT: Potential Spring4Shell attempt detected");
                    log.warn("  Parameter name: {}", paramName);
                    log.warn("  Source IP: {}", getClientIp(request));
                    log.warn("  User-Agent: {}", request.getHeader("User-Agent"));
                    log.warn("  Endpoint: {}", request.getRequestURI());

                    // Could also block the request:
                    // response.sendError(HttpServletResponse.SC_BAD_REQUEST);
                    // return false;
                }
            }

            return true;
        }

        private String getClientIp(HttpServletRequest request) {
            String xForwardedFor = request.getHeader("X-Forwarded-For");
            if (xForwardedFor == null || xForwardedFor.isEmpty()) {
                return request.getRemoteAddr();
            }
            return xForwardedFor.split(",")[0].trim();
        }
    }
}

@RestControllerAdvice
public class Spring4ShellExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(Spring4ShellExceptionHandler.class);

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorResponse> handleException(Exception e, WebRequest request) {
        // Log any binding errors that might indicate exploitation attempt
        if (e.getMessage() != null && 
            (e.getMessage().contains("class") || e.getMessage().contains("classLoader"))) {
            log.warn("Potential exploitation attempt - binding error: {}", e.getMessage());
        }

        return new ResponseEntity<>(
            new ErrorResponse("Invalid request"),
            HttpStatus.BAD_REQUEST
        );
    }

    public static class ErrorResponse {
        private String message;

        public ErrorResponse(String message) {
            this.message = message;
        }

        public String getMessage() { return message; }
    }
}
```

**Tier 3: Build-Time & Deployment Validation**
```java
package com.acme.boot;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.event.EventListener;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.core.SpringVersion;

@SpringBootApplication
public class SecureApplication {

    private static final Logger log = LoggerFactory.getLogger(SecureApplication.class);

    public static void main(String[] args) {
        SpringApplication.run(SecureApplication.class, args);
    }

    /**
     * SECURE: Validate Spring Framework version at startup.
     * Fails fast if vulnerable version detected.
     */
    @EventListener(ApplicationReadyEvent.class)
    public void validateSpringVersion() {
        String springVersion = SpringVersion.getVersion();
        log.info("Spring Framework version: {}", springVersion);

        // Check for vulnerable Spring Framework versions
        if (isVulnerableVersion(springVersion)) {
            log.error("CRITICAL: Vulnerable Spring Framework version detected: {}", springVersion);
            log.error("Spring4Shell (CVE-2022-22965) is NOT patched in this version");
            log.error("Required versions: 5.3.18+ or 5.2.20+");
            throw new SecurityException(
                "Vulnerable Spring Framework version. Please upgrade to patched version."
            );
        }

        log.info("Spring Framework version is secure");
    }

    private boolean isVulnerableVersion(String version) {
        // Vulnerable versions: 5.3.0-5.3.17 and 5.2.0-5.2.19
        if (version.startsWith("5.3")) {
            String patch = version.substring(4).split("\\.")[0];
            try {
                int patchNum = Integer.parseInt(patch.replaceAll("[^0-9]", ""));
                return patchNum < 18;  // Vulnerable if < 5.3.18
            } catch (Exception e) {
                return true;  // Fail secure if we can't parse
            }
        }

        if (version.startsWith("5.2")) {
            String patch = version.substring(4).split("\\.")[0];
            try {
                int patchNum = Integer.parseInt(patch.replaceAll("[^0-9]", ""));
                return patchNum < 20;  // Vulnerable if < 5.2.20
            } catch (Exception e) {
                return true;  // Fail secure
            }
        }

        // Earlier versions (5.0, 5.1) are vulnerable but not as commonly used
        if (version.startsWith("5.0") || version.startsWith("5.1")) {
            return true;
        }

        return false;
    }
}
```

### Tier 2: Essential Defenses

Apply defense-in-depth controls including input validation, output encoding, and security headers.

### Tier 3: Production Hardening

Implement comprehensive logging, monitoring, and automated security testing.
